22	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
23	// The target can be a remote name (e.g., "origin") or a URL for direct push.
24	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
25	// no remote tracking refs — git itself handles the no-op case.
26	// Does not check any settings — callers are responsible for gating.
27	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
28		repo, err := OpenRepository(ctx)
29		if err != nil {
30			return nil //nolint:nilerr // Hook must be silent on failure
31		}
32	
33		// Check if branch exists locally
34		branchRef := plumbing.NewBranchReferenceName(branchName)
35		localRef, err := repo.Reference(branchRef, true)
36		if err != nil {
37			// No branch, nothing to push
38			return nil //nolint:nilerr // Expected when no sessions exist yet
39		}
40	
41		// Only check remote tracking refs when target is a remote name (not a URL).
42		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
43		if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
44			return nil
45		}
46	
47		return doPushBranch(ctx, target, branchName)
48	}
