50	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
51	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
52	func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
53		// Check for remote tracking ref: refs/remotes/<remote>/<branch>
54		remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
55		remoteRef, err := repo.Reference(remoteRefName, true)
56		if err != nil {
57			// Remote branch doesn't exist yet - we have content to push
58			return true
59		}
60	
61		// If local and remote point to same commit, nothing to sync
62		// This is the only case where we skip - any difference needs handling
63		return localHash != remoteRef.Hash()
64	}
