66	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
67	// The target can be a remote name or a URL.
68	func doPushBranch(ctx context.Context, target, branchName string) error {
69		displayTarget := target
70		if isURL(target) {
71			displayTarget = "checkpoint remote"
72		}
73	
74		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
75		stop := startProgressDots(os.Stderr)
76	
77		// Try pushing first
78		if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
79			finishPush(ctx, stop, result, target)
80			return nil
81		}
82		stop("")
83	
84		// Push failed - likely non-fast-forward. Try to fetch and rebase.
85		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
86		stop = startProgressDots(os.Stderr)
87	
88		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
89			stop("")
90			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
91			printCheckpointRemoteHint(target)
92			return nil // Don't fail the main push
93		}
94		stop(" done")
95	
96		// Try pushing again after rebase
97		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
98		stop = startProgressDots(os.Stderr)
99	
100		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
101			stop("")
102			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
103			printCheckpointRemoteHint(target)
104		} else {
105			finishPush(ctx, stop, result, target)
106		}
107	
108		return nil
109	}
