121	// settingsHintOnce ensures the settings commit hint prints at most once per process.
122	var settingsHintOnce sync.Once
123	
124	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
125	var checkpointsV2MigrationHintOnce sync.Once
