127	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
128	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
129	// entire.io discovers the external checkpoint repo by reading the committed project
130	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
131	// (not just in settings.local.json or uncommitted local changes).
132	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
133	// single pre-push invocation.
134	func printSettingsCommitHint(ctx context.Context, target string) {
135		if !isURL(target) {
136			return
137		}
138		settingsHintOnce.Do(func() {
139			if isCheckpointRemoteCommitted(ctx) {
140				return
141			}
142			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
143		})
144	}
