146	// printCheckpointsV2MigrationHint prints a hint when the committed project
147	// settings enable checkpoints_version: 2 AND there are v1 checkpoints that have
148	// not yet been mirrored into v2. Suppressed when v2 already has every v1
149	// checkpoint (nothing to migrate) so the hint does not become noise once the
150	// migration is done.
151	func printCheckpointsV2MigrationHint(ctx context.Context) {
152		checkpointsV2MigrationHintOnce.Do(func() {
153			if !isCheckpointsVersion2Committed(ctx) {
154				return
155			}
156			if !hasUnmigratedV1Checkpoints(ctx) {
157				return
158			}
159			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2. Run 'entire migrate --checkpoints v2' to migrate existing checkpoints to v2.")
160			fmt.Fprintln(os.Stderr, "[entire] Use 'entire migrate --checkpoints v2 --force' to rewrite all checkpoints in v2.")
161		})
162	}
