164	// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
165	// entry in v2. Any failure opening the repo or listing either store is treated
166	// as "no migration needed" so we stay silent instead of printing a speculative
167	// hint — the hint is advisory and should never be the reason a push gets noisy.
168	func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
169		repo, err := OpenRepository(ctx)
170		if err != nil {
171			return false
172		}
173		v1List, err := checkpoint.NewGitStore(repo).ListCommitted(ctx)
174		if err != nil || len(v1List) == 0 {
175			return false
176		}
177		v2List, err := checkpoint.NewV2GitStore(repo, "").ListCommitted(ctx)
178		if err != nil {
179			return false
180		}
181		v2Set := make(map[string]struct{}, len(v2List))
182		for _, info := range v2List {
183			v2Set[info.CheckpointID.String()] = struct{}{}
184		}
185		for _, info := range v1List {
186			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
187				return true
188			}
189		}
190		return false
191	}
