193	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
194	// at HEAD contains a valid checkpoint_remote configuration. This is the true
195	// discoverability check: entire.io reads from committed project settings, not from
196	// local overrides or uncommitted changes.
197	func isCheckpointRemoteCommitted(ctx context.Context) bool {
198		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
199		output, err := cmd.Output()
200		if err != nil {
201			return false // file doesn't exist at HEAD
202		}
203		// Parse the committed content and check for checkpoint_remote
204		committed, err := settings.LoadFromBytes(output)
205		if err != nil {
206			return false
207		}
208		return committed.GetCheckpointRemote() != nil
209	}
