211	// isCheckpointsVersion2Committed returns true if the committed .entire/settings.json
212	// at HEAD sets checkpoints_version to 2.
213	func isCheckpointsVersion2Committed(ctx context.Context) bool {
214		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
215		output, err := cmd.Output()
216		if err != nil {
217			return false
218		}
219		committed, err := settings.LoadFromBytes(output)
220		if err != nil {
221			return false
222		}
223		return committed.CheckpointsVersion() == 2
