232	// parsePushResult checks git push --porcelain output for ref status flags.
233	// In porcelain mode, each ref gets a tab-delimited status line:
234	//
235	//	<flag>\t<from>:<to>\t<summary>
236	//
237	// where flag '=' means the ref was already up-to-date. This is locale-independent,
238	// unlike the human-readable "Everything up-to-date" message.
239	func parsePushResult(output string) pushResult {
240		for _, line := range strings.Split(output, "\n") {
241			if strings.HasPrefix(line, "=\t") {
242				return pushResult{upToDate: true}
243			}
244		}
245		return pushResult{upToDate: false}
246	}
