248	// finishPush stops the progress dots and prints "already up-to-date" or "done"
249	// depending on the push result. Only prints the settings commit hint when new
250	// content was actually pushed.
251	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
252		if result.upToDate {
253			stop(" already up-to-date")
254		} else {
255			stop(" done")
256			printSettingsCommitHint(ctx, target)
257		}
258		printCheckpointsV2MigrationHint(ctx)
259	}
