261	// tryPushSessionsCommon attempts to push the sessions branch.
262	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
263		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
264		defer cancel()
265	
266		// Use --no-verify to prevent recursive hook calls.
267		// Use --porcelain for machine-readable, locale-independent output.
268		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", "--porcelain", remote, branchName)
269	
270		output, err := cmd.CombinedOutput()
271		outputStr := string(output)
272		if err != nil {
273			// Check if it's a non-fast-forward error (we can try to recover)
274			if strings.Contains(outputStr, "non-fast-forward") ||
275				strings.Contains(outputStr, "rejected") {
276				return pushResult{}, errors.New("non-fast-forward")
277			}
278			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
279		}
280	
281		return parsePushResult(outputStr), nil
282	}
