284	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
285	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
286	// always apply cleanly.
287	// The target can be a remote name or a URL.
288	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
289		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
290		defer cancel()
291	
292		fetchTarget, err := ResolveFetchTarget(ctx, target)
293		if err != nil {
294			return fmt.Errorf("resolve fetch target: %w", err)
295		}
296	
297		// Determine fetch refspec. When the resolved fetch target is a URL, use a
298		// temp ref; when it's still a remote name, use the standard remote-tracking
299		// ref.
300		var fetchedRefName plumbing.ReferenceName
301		var refSpec string
302		usedTempRef := isURL(fetchTarget)
303		if usedTempRef {
304			tmpRef := "refs/entire-fetch-tmp/" + branchName
305			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
306			fetchedRefName = plumbing.ReferenceName(tmpRef)
307		} else {
308			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
309			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
310		}
311	
312		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
313		// Use --filter=blob:none for a partial fetch that downloads only commits
314		// and trees, skipping blobs. The merge only needs the tree structure to
315		// combine entries; blobs are already local or fetched on demand.
316		fetchArgs := AppendFetchFilterArgs(ctx, []string{"fetch", "--no-tags", fetchTarget, refSpec})
317		fetchCmd := CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
318		if output, err := fetchCmd.CombinedOutput(); err != nil {
319			return fmt.Errorf("fetch failed: %s", output)
320		}
321	
322		repo, err := OpenRepository(ctx)
323		if err != nil {
324			return fmt.Errorf("failed to open git repository: %w", err)
325		}
326	
327		// Reconcile disconnected metadata branches before rebasing.
328		// The fetch above updated the remote-tracking ref, so reconciliation
329		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
330		// this cherry-picks local commits onto remote tip, updating the local ref.
331		// If reconciliation fails, abort — proceeding to rebase on disconnected
332		// branches would silently combine unrelated histories.
333		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
334			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
335		}
336	
337		// Get local branch (re-read after potential reconciliation update)
338		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
339		if err != nil {
340			return fmt.Errorf("failed to get local ref: %w", err)
341		}
342	
343		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
344		remoteRef, err := repo.Reference(fetchedRefName, true)
345		if err != nil {
346			return fmt.Errorf("failed to get remote ref: %w", err)
347		}
348	
349		// If local is already at or behind remote, fast-forward
350		if localRef.Hash() == remoteRef.Hash() {
351			return nil
352		}
353	
354		// Find merge base
355		repoPath, err := getRepoPath(repo)
356		if err != nil {
357			return fmt.Errorf("failed to get repo path: %w", err)
358		}
359		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
360		if err != nil {
361			return fmt.Errorf("failed to find merge base: %w", err)
362		}
363	
364		// If local is ancestor of remote (merge base == local), fast-forward to remote
365		if mergeBase == localRef.Hash() {
366			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
367			if err := repo.Storer.SetReference(ref); err != nil {
368				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
369			}
370			if usedTempRef {
371				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
372			}
373			return nil
374		}
375	
376		// Collect commits reachable from local but not from remote and cherry-pick
377		// them onto the remote tip. This preserves local-only commits even when the
378		// local metadata branch already contains old merge commits, while avoiding
379		// replaying shared ancestors older than the true merge-base.
380		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
381		if err != nil {
382			return fmt.Errorf("failed to collect local commits: %w", err)
383		}
384	
385		if len(localCommits) == 0 {
386			// No local-only commits — just point to remote
387			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
388			if err := repo.Storer.SetReference(ref); err != nil {
389				return fmt.Errorf("failed to update branch ref: %w", err)
390			}
391			if usedTempRef {
392				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
393			}
394			return nil
395		}
396	
397		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
398		if err != nil {
399			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
400		}
401	
402		// Update branch ref
403		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
404		if err := repo.Storer.SetReference(newRef); err != nil {
405			return fmt.Errorf("failed to update branch ref: %w", err)
406		}
407	
408		// Clean up temp ref if we used one (best-effort, not critical if it fails)
409		if usedTempRef {
410			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
411		}
412	
413		return nil
414	}
