416	// getMergeBase returns the merge base hash of two commits, or an error if they
417	// have no common ancestor.
418	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
419		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
420		defer cancel()
421	
422		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
423		cmd.Dir = repoPath
424		output, err := cmd.Output()
425		if err != nil {
426			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
427		}
428	
429		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
430	}
431	
432	// collectCommitsSince returns non-merge commits reachable from tip but not from
433	// exclude, ordered oldest-first in topological order.
434	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
435		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
436		defer cancel()
437	
438		// cherryPickOnto computes each commit's delta against its first parent, so
439		// replaying merge commits would incorrectly re-apply changes that arrived via
440		// non-first-parent history. Limit the replay set to non-merge commits.
441		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
442		cmd.Dir = repoPath
443		output, err := cmd.Output()
444		if err != nil {
445			return nil, fmt.Errorf("git rev-list failed: %w", err)
446		}
447	
448		lines := strings.Fields(string(output))
449		if len(lines) > MaxCommitTraversalDepth {
450			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
451		}
452	
453		commits := make([]*object.Commit, 0, len(lines))
454		for _, line := range lines {
455			hash := plumbing.NewHash(line)
456			commit, commitErr := repo.CommitObject(hash)
457			if commitErr != nil {
458				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
459			}
460			if len(commit.ParentHashes) > 1 {
461				continue
462			}
463			commits = append(commits, commit)
464		}
465	
466		return commits, nil
467	}
