469	// startProgressDots prints dots to w every second until the returned stop function
470	// is called. The stop function prints the given suffix and a newline.
471	func startProgressDots(w io.Writer) func(suffix string) {
472		done := make(chan struct{})
473		stopped := make(chan struct{})
474		go func() {
475			defer close(stopped)
476			ticker := time.NewTicker(time.Second)
477			defer ticker.Stop()
478			for {
479				select {
480				case <-done:
481					return
482				case <-ticker.C:
483					fmt.Fprint(w, ".")
484				}
485			}
486		}()
487		return func(suffix string) {
488			close(done)
489			<-stopped // Wait for goroutine to finish before writing suffix
490			fmt.Fprintln(w, suffix)
491		}
492	}
