499	// createMergeCommitCommon creates a merge commit with multiple parents.
500	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
501		authorName, authorEmail := GetGitAuthorFromRepo(repo)
502		now := time.Now()
503		sig := object.Signature{
504			Name:  authorName,
505			Email: authorEmail,
506			When:  now,
507		}
508	
509		commit := &object.Commit{
510			TreeHash:     treeHash,
511			ParentHashes: parents,
512			Author:       sig,
513			Committer:    sig,
514			Message:      message,
515		}
516	
517		checkpoint.SignCommitBestEffort(ctx, commit)
518	
519		obj := repo.Storer.NewEncodedObject()
520		if err := commit.Encode(obj); err != nil {
521			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
522		}
523	
524		hash, err := repo.Storer.SetEncodedObject(obj)
525		if err != nil {
526			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
527		}
528	
529		return hash, nil
530	}
